def count_all_one_squares(matrix):
 dp=[0]*(len(matrix[0])+1);answer=0
 for row in matrix:
  previous=0
  for j,value in enumerate(row,1):
   old=dp[j];dp[j]=1+min(dp[j],dp[j-1],previous) if value else 0;answer+=dp[j];previous=old
 return answer

